; ROM bank $35: species records
; The annotated listing of this bank is build/listing/bank35.asm.

SECTION "Bank 35", ROMX[$4000], BANK[$35]
    db $35

; copies the whole 47-byte species record of monster id wSpeciesIdLo/Hi to wSpeciesRecord; byte 0 is
; the family (E-0069)
LoadSpeciesRecord::
    ld de, wSpeciesRecord
    ld b, $2f
    call CopySpeciesRecordPrefix
    ret

; copies byte 0 of the species record of monster id wSpeciesIdLo/Hi, the family (0 Slime ... 9
; Water, 10 Boss; $FF for an unused id), to wSpeciesRecord (E-0069)
LoadSpeciesFamily::
    ld de, wSpeciesRecord
    ld b, $01
    call CopySpeciesRecordPrefix
    ret

; copies bytes 0-1 of the species record of monster id wSpeciesIdLo/Hi (the family and byte 1) to
; wSpeciesRecord (E-0069)
LoadSpeciesRecordWord0::
    ld de, wSpeciesRecord
    ld b, $02
    call CopySpeciesRecordPrefix
    ret

; B = byte count, DE = destination: copies the first B bytes of the species record for monster id
; wSpeciesIdLo/Hi (pointer table SpeciesRecordPointers, 384 entries, 47-byte records) to DE (E-0062,
; E-0069)
CopySpeciesRecordPrefix::
    push bc
    push de
    ld a, [wSpeciesIdLo]
    ld c, a
    ld a, [wSpeciesIdHi]
    ld b, a
    sla c
    rl b
    ld hl, SpeciesRecordPointers
    add hl, bc
    ld e, [hl]
    inc hl
    ld h, [hl]
    ld l, e
    pop de
    pop bc

.loop:
    ld a, [hli]
    ld [de], a
    inc de
    dec b
    jr nz, .loop
    ret

; CopySpeciesRecordPrefix reads the word at $403B + 2 * monster id (wSpeciesIdLo/Hi) and copies the
; first B bytes of the record it points at (E-0062, E-0069); 384 words, 324 distinct records
; (E-0253, C1)
; record: 47-byte species record
SpeciesRecordPointers::
    dw SpeciesRecords ; id 0
    dw SpeciesRecord_DrakSlime ; id 1 DrakSlime
    dw SpeciesRecord_SpotSlime ; id 2 SpotSlime
