; the 324 records SpeciesRecordPointers points at, 47 bytes each and contiguous up to $7EB7; each is
; labelled SpeciesRecord_<monster> after the first id that uses it; byte 0 is the family (E-0069)
; and byte 7 the EXP curve (E-0148); the other bytes are not read here (E-0253, C1)
; record: family; bytes 1-5; base level cap; EXP curve; natural skills; bytes 11-15; growth row;
; byte 17; resistances; bytes 45-46
SpeciesRecords::
SpeciesRecord_000::
    db $ff ; id 0: family (StringTable_MonsterFamilies index; $FF unused)
    db $00 ; sex-ratio class (C1, E-0307)
    db $00 ; cannot be tripped, bit 0 (C1, E-0310)
    db $00 ; metal body, bit 0 (C1, E-0310)
    db $00 ; join-chance class (7 = never; C1, E-0306)
    db $00 ; byte 5 (never read)
    db $00 ; base level cap (C1, E-0299)
    db $00 ; EXP curve: ExpTable row (wSpeciesExpCurve)
    db $ff, $ff, $ff ; natural skills (C1, E-0299)
    db $00 ; field ability (StringTable_FieldAbilities index; C2, E-0313)
    db $00, $00, $00, $00, $00, $00 ; six stat growth rows (HP, MP, ATK, DEF, AGL, INT; C1, E-0309)
    db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00 ; 27 base resistance levels (C1, E-0299)
    dw $0000 ; base EXP (C1, E-0310)
SpeciesRecord_DrakSlime::
    db $00 ; id 1: family (StringTable_MonsterFamilies index; $FF unused)
    db $02 ; sex-ratio class (C1, E-0307)
    db $00 ; cannot be tripped, bit 0 (C1, E-0310)
    db $00 ; metal body, bit 0 (C1, E-0310)
    db $04 ; join-chance class (7 = never; C1, E-0306)
    db $00 ; byte 5 (never read)
    db $2d ; base level cap (C1, E-0299)
    db $0d ; EXP curve: ExpTable row (wSpeciesExpCurve)
    db SKILL_BEDRAGON, SKILL_FIREAIR, SKILL_SUCKAIR ; natural skills (C1, E-0299)
    db $00 ; field ability (StringTable_FieldAbilities index; C2, E-0313)
    db $10, $0a, $0d, $08, $14, $10 ; six stat growth rows (HP, MP, ATK, DEF, AGL, INT; C1, E-0309)
    db $01, $01, $01, $00, $00, $00, $02, $02, $02, $02, $02, $02, $02, $02, $03, $02, $02, $01, $00, $01, $00, $00, $00, $00, $00, $00, $00 ; 27 base resistance levels (C1, E-0299)
    dw $004f ; base EXP (C1, E-0310)
SpeciesRecord_SpotSlime::
    db $00 ; id 2: family (StringTable_MonsterFamilies index; $FF unused)
    db $02 ; sex-ratio class (C1, E-0307)
    db $00 ; cannot be tripped, bit 0 (C1, E-0310)
    db $00 ; metal body, bit 0 (C1, E-0310)
    db $03 ; join-chance class (7 = never; C1, E-0306)
    db $00 ; byte 5 (never read)
    db $23 ; base level cap (C1, E-0299)
    db $0a ; EXP curve: ExpTable row (wSpeciesExpCurve)
    db SKILL_CALLHELP, SKILL_LUSHLICKS, SKILL_IMITATE ; natural skills (C1, E-0299)
    db $00 ; field ability (StringTable_FieldAbilities index; C2, E-0313)
    db $11, $01, $11, $04, $11, $08 ; six stat growth rows (HP, MP, ATK, DEF, AGL, INT; C1, E-0309)
    db $00, $00, $00, $00, $00, $00, $02, $02, $02, $02, $02, $02, $03, $03, $02, $02, $00, $00, $00, $00, $00, $01, $01, $01, $01, $01, $00 ; 27 base resistance levels (C1, E-0299)
    dw $0041 ; base EXP (C1, E-0310)
SpeciesRecord_WingSlime::
    db $00 ; id 3: family (StringTable_MonsterFamilies index; $FF unused)
    db $02 ; sex-ratio class (C1, E-0307)
    db $01 ; cannot be tripped, bit 0 (C1, E-0310)
    db $00 ; metal body, bit 0 (C1, E-0310)
    db $04 ; join-chance class (7 = never; C1, E-0306)
    db $01 ; byte 5 (never read)
    db $23 ; base level cap (C1, E-0299)
    db $0a ; EXP curve: ExpTable row (wSpeciesExpCurve)
    db SKILL_WINDBEAST, SKILL_SQUALLHIT, SKILL_TAILWIND ; natural skills (C1, E-0299)
    db $00 ; field ability (StringTable_FieldAbilities index; C2, E-0313)
    db $0d, $02, $0b, $0b, $18, $08 ; six stat growth rows (HP, MP, ATK, DEF, AGL, INT; C1, E-0309)
